def _decimal(amount):
    """Render an amount as a bare decimal string, e.g. 12.50."""
    sign = "-" if amount < 0 else ""
    whole, cents = divmod(abs(amount), 100)
    return "%s%d.%02d" % (sign, whole, cents)


def format_receipt_total(amount):
    """Render the order total for the emailed receipt, e.g. 12.50 USD."""
    return "%s USD" % _decimal(amount)


def format_price(cents):
    """Render a price for the checkout page, e.g. $12.50."""
    return "$%s" % _decimal(cents)
```

